// CSD_RATIONALE_BEGIN
// Root-cause diagnosis: the previous strategy closes the constrained span the
// moment parser.IsCompletePrefix fires, which happens after a single variable
// name token (e.g., "n"). This produces ~28 single-token spans per example.
// The evaluator extracts the LAST span; single-variable spans yield 0% accuracy.
//
// Fix: separate reasoning from answer generation into three phases.
//   Phase 1 — Free unconstrained reasoning with NO span detection.
//             The model thinks freely; natural "<<n>>" sequences pass through
//             as raw tokens (not constrained spans), avoiding the tiny-span trap.
//   Phase 2 — Force-open exactly ONE final constrained span (OpenConstrainedSpan).
//   Phase 3 — Generate the complete answer expression constrained
//             (AdaptiveConstrainedStep). Do NOT close eagerly on IsCompletePrefix;
//             let the model choose to stop by returning EOS. Use
//             CloseSpanWithinBudget at budget pressure (≤ 2 steps remaining).
//
// The forced final span will contain the full expression (e.g.,
// <<n * frac_1 * frac_2>>), which the evaluator extracts as the answer.
// Guidance explicitly discourages intermediate per-variable spans.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (unconstrained, NO span detection): insideConstrainedOut never flips
//   inside the loop body (no span-entry call). If it was true on entry the loop
//   condition !insideConstrainedOut prevents execution; entry precondition
//   provides validity. If it was false, it remains false and the implication
//   is vacuous throughout. ✓
//
//   Phase 2 (OpenConstrainedSpan): sets currentConstrainedOut := []; the
//   precondition parser.IsValidPrefix([]) holds. insideConstrainedOut := true. ✓
//
//   Phase 3 — CloseSpanWithinBudget: postcondition directly asserts
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Phase 3 — EOS with CloseConstrainedSpan: sets insideConstrainedOut := false,
//   making the implication vacuously true; currentConstrainedOut := []. ✓
//
//   Phase 3 — EOS without close (IsCompletePrefix false or no spare step):
//   insideConstrainedOut stays true; currentConstrainedOut unchanged by the EOS
//   branch; invariant holds from previous iteration. ✓
//
//   Phase 3 — normal step (AdaptiveConstrainedStep + AppendConstrainedToken):
//   AdaptiveConstrainedStep hard-masks to parser-valid next tokens plus EOS;
//   AppendConstrainedToken extends currentConstrainedOut by that valid token,
//   preserving IsValidPrefix. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps = 0. ✓
//   Phase 1: steps += 1 each iteration; generated grows by at most 1 (EOS breaks
//   without appending). ✓
//   Phase 2: OpenConstrainedSpan appends exactly one token (<<); steps += 1. ✓
//   Phase 3 — CloseSpanWithinBudget: closeBudget = maxSteps - steps; postcondition
//   gives |generated_new| <= |generated_old| + closeBudget; after steps := maxSteps,
//   |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//   Phase 3 — EOS with CloseConstrainedSpan: one step for generate, one for close;
//   generated grows by at most 1 (the ">>" delimiter); invariant maintained. ✓
//   Phase 3 — EOS without close: steps += 1; generated unchanged (EOS not
//   appended); invariant trivially maintained. ✓
//   Phase 3 — normal step: steps += 1; AppendConstrainedToken appends exactly one
//   token to generated; invariant maintained. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the end, write the complete Python answer expression " +
  "in ONE final << >> span, e.g. <<n * k // m>> or <<int(x * (1 + r/100))>>. " +
  "Use variable names without braces. Do not wrap individual variables in " +
  "separate << >> spans during your reasoning.");

var steps: nat := 0;
var narrowThreshold: nat := 12;
var reasoningSteps: nat := if maxSteps > 30 then maxSteps - 30 else 0;

// Phase 1: Free unconstrained reasoning — no span detection.
while steps < reasoningSteps && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases reasoningSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

// Phase 2: Force-open the final answer span (if not already inside one).
if steps < maxSteps && !insideConstrainedOut {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained generation for the complete answer expression.
// Key change: do NOT eagerly close on IsCompletePrefix; let the model end by EOS.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if maxSteps - steps <= 2 {
    // Budget pressure: close gracefully within remaining budget.
    var closeBudget := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
  } else {
    // Normal constrained generation: let model choose to extend or stop (EOS).
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Model wants to stop; close the span if it parses as complete.
      // At this point steps <= maxSteps - 2 (from the > 2 guard above),
      // so steps < maxSteps holds after the AdaptiveConstrainedStep increment.
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(
          lm, parser, generated, currentConstrainedOut
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

cost := steps;

